import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Papa from "papaparse";
import "../App.css";

function LibraryPage() {
  const [searchText, setSearchText] = useState("");
  const [activeCategory, setActiveCategory] = useState("blog");
  const [newsData, setNewsData] = useState([]);
  const [blogData, setBlogData] = useState([]);
  const [paperData, setPaperData] = useState([]);
  const [paperKeywords, setPaperKeywords] = useState([]);
  const [activeKeyword, setActiveKeyword] = useState("all");

  // Animation variants
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  // CSV 파일에서 데이터 로드
  useEffect(() => {
    // hanssem_contents.csv 로드
    fetch("/hanssem_contents.csv")
      .then((response) => response.text())
      .then((csvText) => {
        Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            const data = results.data;

            // 날짜 파싱 함수 (YYYY-MM-DD 형식)
            const parseDate = (dateStr) => {
              if (!dateStr) return new Date(0);
              const parts = dateStr.split('-');
              if (parts.length === 3) {
                return new Date(parts[0], parts[1] - 1, parts[2]);
              }
              return new Date(dateStr);
            };

            // 뉴스와 블로그 데이터 분리 및 최신순 정렬
            const news = data
              .filter(item => item.source === 'news')
              .sort((a, b) => parseDate(b.pubdate) - parseDate(a.pubdate))
              .slice(0, 12); // 최신 12개

            const blog = data
              .filter(item => item.source === 'blog')
              .sort((a, b) => parseDate(b.pubdate) - parseDate(a.pubdate))
              .slice(0, 12); // 최신 12개

            setNewsData(news);
            setBlogData(blog);
          },
        });
      })
      .catch((error) => console.error("hanssem_contents CSV 로드 오류:", error));

    // riss_FIN2.csv 로드 (논문 데이터)
    fetch("/riss_FIN2.csv")
      .then((response) => response.text())
      .then((csvText) => {
        Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            const data = results.data.map((item, index) => ({
              id: `paper_${index}`,
              database: item.database,
              keyword: item.keyword,
              title: item.title,
              authors: item.authors,
              publisher: item.publisher,
              journal: item.journal,
              issue: item.issue,
              year: item.year,
              link: item.link,
            }));

            setPaperData(data);

            // keyword로 카테고리 추출
            const uniqueKeywords = [...new Set(data.map((item) => item.keyword))].filter(Boolean);
            setPaperKeywords(uniqueKeywords);
          },
        });
      })
      .catch((error) => console.error("riss_FIN2 CSV 로드 오류:", error));
  }, []);

  // 카테고리 데이터
  const categories = [
    {
      id: "news",
      name: "News & Blogs",
      subtitle: "뉴스 & 블로그",
      icon: "fas fa-newspaper",
    },
    {
      id: "blog",
      name: "Blog Posts",
      subtitle: "블로그 포스트",
      icon: "fas fa-blog",
    },
    {
      id: "paper",
      name: "Research Papers",
      subtitle: "논문",
      icon: "fas fa-file-alt",
    },
  ];

  // 논문 필터링
  const filteredPapers = activeKeyword === "all"
    ? paperData
    : paperData.filter(paper => paper.keyword === activeKeyword);


  return (
    <main
      style={{
        minHeight: "100vh",
        background: "linear-gradient(180deg, #f8f9fa 0%, #e9ecef 100%)",
        paddingTop: "0",
        marginTop: "0",
      }}
    >
      {/* Header Section */}
      <motion.div
        style={{
          textAlign: "center",
          padding: "60px 20px 40px",
          background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
          color: "#fff",
          marginBottom: "0",
          marginTop: "0",
        }}
        initial="hidden"
        animate="visible"
        variants={fadeUp}
      >
        <motion.h1
          style={{
            fontSize: "clamp(2.5rem, 5vw, 3.5rem)",
            fontWeight: 800,
            margin: "0 0 15px",
            textShadow: "2px 2px 4px rgba(0,0,0,0.2)",
          }}
          variants={fadeUp}
        >
          Asset Library
        </motion.h1>
        <motion.p
          style={{
            fontSize: "1.2rem",
            opacity: 0.95,
            margin: 0,
          }}
          variants={fadeUp}
        >
          인테리어 디자인 자료와 영감을 찾아보세요
        </motion.p>
      </motion.div>

      {/* Main Content */}
      <div style={{ display: "flex", maxWidth: "1400px", margin: "0 auto", gap: "30px" }}>
        {/* Sidebar */}
        <motion.aside
          style={{
            width: "280px",
            background: "#fff",
            padding: "30px 25px",
            borderRadius: "20px",
            boxShadow: "0 10px 30px rgba(0, 0, 0, 0.08)",
            margin: "30px 0 30px 30px",
            height: "fit-content",
            position: "sticky",
            top: "100px",
          }}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          variants={fadeUp}
        >
          <h2
            style={{
              fontSize: "1.5rem",
              fontWeight: 700,
              color: "#333",
              marginTop: 0,
              marginBottom: "30px",
            }}
          >
            카테고리
          </h2>

          {categories.map((category, index) => (
            <motion.div
              key={index}
              onClick={() => setActiveCategory(category.id)}
              style={{
                marginBottom: "15px",
                padding: "15px",
                borderRadius: "12px",
                cursor: "pointer",
                transition: "all 0.3s ease",
                background: activeCategory === category.id
                  ? "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                  : "#f8f9fa",
                boxShadow: activeCategory === category.id
                  ? "0 5px 15px rgba(102, 126, 234, 0.3)"
                  : "none",
              }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              <div style={{
                display: "flex",
                alignItems: "center",
                gap: "10px",
                marginBottom: "8px",
              }}>
                <i
                  className={category.icon}
                  style={{
                    fontSize: "1.2rem",
                    color: activeCategory === category.id ? "#fff" : "#667eea",
                  }}
                ></i>
                <h3
                  style={{
                    fontSize: "1rem",
                    fontWeight: 600,
                    color: activeCategory === category.id ? "#fff" : "#333",
                    margin: 0,
                  }}
                >
                  {category.name}
                </h3>
              </div>
              <p
                style={{
                  fontSize: "0.85rem",
                  color: activeCategory === category.id ? "rgba(255,255,255,0.9)" : "#6c757d",
                  paddingLeft: "32px",
                  margin: 0,
                }}
              >
                {category.subtitle}
              </p>
            </motion.div>
          ))}
        </motion.aside>

        {/* Content Area */}
        <div style={{ flex: 1, padding: "30px 30px 30px 0" }}>
          {/* Search Bar */}
          <motion.div
            style={{
              display: "flex",
              gap: "12px",
              marginBottom: "40px",
              flexWrap: "wrap",
            }}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            variants={fadeUp}
          >
            <input
              type="text"
              placeholder="Search any documents..."
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{
                flex: 1,
                minWidth: "250px",
                padding: "14px 20px",
                border: "2px solid #e9ecef",
                borderRadius: "12px",
                fontSize: "1rem",
                transition: "all 0.3s ease",
              }}
              onFocus={(e) => {
                e.target.style.borderColor = "#667eea";
                e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
              }}
              onBlur={(e) => {
                e.target.style.borderColor = "#e9ecef";
                e.target.style.boxShadow = "none";
              }}
            />
            <motion.button
              style={{
                padding: "14px 30px",
                background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                color: "#fff",
                border: "none",
                borderRadius: "12px",
                fontSize: "1rem",
                fontWeight: 600,
                cursor: "pointer",
                boxShadow: "0 8px 20px rgba(102, 126, 234, 0.3)",
              }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              Search
            </motion.button>
            <motion.button
              style={{
                padding: "14px 25px",
                background: "linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)",
                color: "#fff",
                border: "none",
                borderRadius: "12px",
                fontSize: "1rem",
                fontWeight: 600,
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                boxShadow: "0 8px 20px rgba(67, 233, 123, 0.3)",
              }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              <i className="fas fa-plus"></i>
              자료 업로드
            </motion.button>
          </motion.div>

          {/* Content Section */}
          {activeCategory === "news" && (
            <motion.section
              style={{ marginBottom: "50px" }}
              initial="hidden"
              animate="visible"
              viewport={{ once: true, amount: 0.2 }}
              variants={staggerContainer}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "25px",
                }}
              >
                <h2 style={{ fontSize: "1.8rem", fontWeight: 700, margin: 0, color: "#333" }}>
                  <i className="fas fa-newspaper" style={{ marginRight: "10px", color: "#667eea" }}></i>
                  최신 뉴스
                </h2>
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                  gap: "20px",
                }}
              >
                {newsData.length > 0 ? (
                  newsData.map((item, index) => (
                    <ContentCard key={index} item={item} variants={fadeUp} />
                  ))
                ) : (
                  <p style={{ color: "#6c757d", gridColumn: "1 / -1" }}>뉴스 데이터가 없습니다.</p>
                )}
              </div>
            </motion.section>
          )}

          {activeCategory === "blog" && (
            <motion.section
              initial="hidden"
              animate="visible"
              viewport={{ once: true, amount: 0.2 }}
              variants={staggerContainer}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "25px",
                }}
              >
                <h2 style={{ fontSize: "1.8rem", fontWeight: 700, margin: 0, color: "#333" }}>
                  <i className="fas fa-blog" style={{ marginRight: "10px", color: "#f093fb" }}></i>
                  최신 블로그
                </h2>
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                  gap: "20px",
                }}
              >
                {blogData.length > 0 ? (
                  blogData.map((item, index) => (
                    <ContentCard key={index} item={item} variants={fadeUp} />
                  ))
                ) : (
                  <p style={{ color: "#6c757d", gridColumn: "1 / -1" }}>블로그 데이터를 불러오는 중...</p>
                )}
              </div>
            </motion.section>
          )}

          {activeCategory === "paper" && (
            <motion.section
              initial="hidden"
              animate="visible"
              viewport={{ once: true, amount: 0.2 }}
              variants={staggerContainer}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "25px",
                }}
              >
                <h2 style={{ fontSize: "1.8rem", fontWeight: 700, margin: 0, color: "#333" }}>
                  <i className="fas fa-file-alt" style={{ marginRight: "10px", color: "#667eea" }}></i>
                  논문
                </h2>
              </div>

              {/* Keyword 필터 */}
              <div style={{ marginBottom: "30px" }}>
                <h3 style={{
                  fontSize: "1.1rem",
                  fontWeight: 600,
                  color: "#495057",
                  marginBottom: "15px"
                }}>
                  키워드 선택
                </h3>
                <div
                  style={{
                    display: "flex",
                    flexWrap: "wrap",
                    gap: "10px",
                  }}
                >
                  <motion.button
                    onClick={() => setActiveKeyword("all")}
                    style={{
                      padding: "10px 20px",
                      border: "none",
                      borderRadius: "20px",
                      fontSize: "0.95rem",
                      fontWeight: 600,
                      cursor: "pointer",
                      transition: "all 0.3s ease",
                      background: activeKeyword === "all"
                        ? "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                        : "#fff",
                      color: activeKeyword === "all" ? "#fff" : "#333",
                      boxShadow: activeKeyword === "all"
                        ? "0 6px 15px rgba(102, 126, 234, 0.3)"
                        : "0 2px 8px rgba(0, 0, 0, 0.08)",
                    }}
                    whileHover={{
                      scale: 1.05,
                      boxShadow: "0 8px 20px rgba(102, 126, 234, 0.4)",
                    }}
                    whileTap={{ scale: 0.95 }}
                  >
                    전체
                  </motion.button>
                  {paperKeywords.map((keyword) => (
                    <motion.button
                      key={keyword}
                      onClick={() => setActiveKeyword(keyword)}
                      style={{
                        padding: "10px 20px",
                        border: "none",
                        borderRadius: "20px",
                        fontSize: "0.95rem",
                        fontWeight: 600,
                        cursor: "pointer",
                        transition: "all 0.3s ease",
                        background: activeKeyword === keyword
                          ? "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                          : "#fff",
                        color: activeKeyword === keyword ? "#fff" : "#333",
                        boxShadow: activeKeyword === keyword
                          ? "0 6px 15px rgba(102, 126, 234, 0.3)"
                          : "0 2px 8px rgba(0, 0, 0, 0.08)",
                      }}
                      whileHover={{
                        scale: 1.05,
                        boxShadow: "0 8px 20px rgba(102, 126, 234, 0.4)",
                      }}
                      whileTap={{ scale: 0.95 }}
                    >
                      {keyword}
                    </motion.button>
                  ))}
                </div>
              </div>

              {/* 논문 목록 */}
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                  gap: "20px",
                }}
              >
                {filteredPapers.length > 0 ? (
                  filteredPapers.map((paper) => (
                    <PaperCard key={paper.id} paper={paper} variants={fadeUp} />
                  ))
                ) : (
                  <p style={{ color: "#6c757d", gridColumn: "1 / -1" }}>논문 데이터를 불러오는 중...</p>
                )}
              </div>
            </motion.section>
          )}
        </div>
      </div>
    </main>
  );
}

// Content Card Component for News and Blog
function ContentCard({ item, variants }) {
  return (
    <motion.a
      href={item.url}
      target="_blank"
      rel="noopener noreferrer"
      style={{
        backgroundColor: "#fff",
        borderRadius: "15px",
        overflow: "hidden",
        boxShadow: "0 5px 15px rgba(0, 0, 0, 0.08)",
        transition: "all 0.3s ease",
        cursor: "pointer",
        position: "relative",
        textDecoration: "none",
        display: "block",
      }}
      variants={variants}
      whileHover={{
        y: -8,
        boxShadow: "0 15px 30px rgba(0, 0, 0, 0.15)",
      }}
    >
      {/* Info */}
      <div style={{ padding: "20px" }}>
        <h3
          style={{
            fontSize: "1.1rem",
            fontWeight: 600,
            color: "#333",
            margin: "0 0 12px",
            lineHeight: "1.5",
            overflow: "hidden",
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
          }}
        >
          {item.title}
        </h3>
        <div style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          fontSize: "0.9rem",
          color: "#6c757d",
        }}>
          <i className="fas fa-calendar-alt" style={{ color: "#667eea" }}></i>
          <span>{item.pubdate}</span>
        </div>
        <div style={{
          marginTop: "12px",
          paddingTop: "12px",
          borderTop: "1px solid #e9ecef",
        }}>
          <span style={{
            fontSize: "0.85rem",
            color: "#667eea",
            fontWeight: 600,
            display: "flex",
            alignItems: "center",
            gap: "5px",
          }}>
            자세히 보기
            <i className="fas fa-arrow-right"></i>
          </span>
        </div>
      </div>
    </motion.a>
  );
}

export default LibraryPage;
